    ["Microphone unavailable. Check your Windows input device."] = "Mikrofon niedostępny. Sprawdź urządzenie wejściowe w systemie Windows.",
    ["Mod logs"] = "Logi moda",
    ["Mod logs such as probe.log and mcm.log are in {path}"] = "Logi moda, takie jak probe.log i mcm.log, znajdują się w: {path}",
    ["Model browser"] = "Przeglądarka modeli",
    ["Models"] = "Modele",
    ["More characters"] = "Więcej postaci",
    ["More models"] = "Więcej modeli",
    ["More than one owned car is nearby. Select or summon the car you want to use."] = "W pobliżu jest więcej niż jeden twój samochód. Wybierz lub przywołaj ten, którego chcesz użyć.",
    ["Move onto open, walkable ground to invite a companion here."] = "Przejdź na otwarty, dostępny teren, aby zaprosić tu towarzysza.",
    ["Multilingual conversations"] = "Rozmowy wielojęzyczne",
    ["NEXT  >"] = "NASTĘPNE  >",
    ["NIGHT CITY"] = "NIGHT CITY",
    ["Natural speech"] = "Naturalna mowa",
    ["Natural speech needs a local voice, so {setting} was switched to {voice}."] = "Naturalna mowa wymaga głosu lokalnego, więc zmieniono ustawienie {setting} na: {voice}.",
    ["Next"] = "Następne",
    ["No clear, reachable companion space on this floor. Move to a wider spot and try again."] = "Brak wolnego, osiągalnego miejsca dla towarzysza na tym piętrze. Przejdź w szersze miejsce i spróbuj ponownie.",
    ["No conversation profile. This model joins as a follower without AI conversations."] = "Brak profilu rozmowy. Ten model dołącza jako podążający za tobą, bez rozmów z AI.",
    ["No entries are available."] = "Brak dostępnych wpisów.",
    ["No entries yet.\nTry another search or tab."] = "Brak wpisów.\nSpróbuj innego wyszukiwania lub karty.",
    ["No matches. Try another name or clear the search."] = "Brak dopasowań. Spróbuj innego imienia lub wyczyść wyszukiwanie.",
    ["No reply arrived. The conversation service may not be running."] = "Nie nadeszła odpowiedź. Usługa rozmów może nie działać.",
    ["No reply received. Your message is in the draft; press Enter to retry."] = "Nie otrzymano odpowiedzi. Twoja wiadomość jest w szkicu; naciśnij Enter, aby spróbować ponownie.",
    ["No settings were supplied."] = "Nie podano żadnych ustawień.",
    ["You: {text}"] = "Ty: {text}",
    ["No speech was heard. Wait for Listening, then speak before you finish."] = "Nie wykryto mowy - poczekaj na Nasłuchiwanie, potem mów, zanim zakończysz.",
    ["None yet"] = "Jeszcze brak",
    ["Not configured"] = "Nie skonfigurowano",
    ["Not installed"] = "Nie zainstalowano",
    ["Not running"] = "Nie działa",
    ["Off"] = "Wyłączone",
    ["OmniVoice is an optional add-on for computers with a capable GPU. Pocket TTS needs nothing extra."] = "OmniVoice to opcjonalny dodatek dla komputerów z wydajnym GPU. Pocket TTS nie wymaga niczego więcej.",
    ["OmniVoice pack"] = "Pakiet OmniVoice",
    ["OmniVoice · Balanced"] = "OmniVoice · Zrównoważona",
    ["OmniVoice · High Quality"] = "OmniVoice · Wysoka jakość",
    ["OmniVoice · Quality"] = "OmniVoice · Jakość",
    ["OmniVoice · Ultra Quality"] = "OmniVoice · Ultra jakość",
    ["On"] = "Włączone",
    ["One file with versions, settings and the latest log lines. It never contains your API key, tokens, voice recordings or conversation text."] = "Jeden plik z wersjami, ustawieniami i najnowszymi wierszami logu. Nigdy nie zawiera twojego klucza API, tokenów, nagrań głosu ani treści rozmów.",
    ["Open"] = "Otwórz",
    ["Opening chat. Waiting for the conversation service."] = "Otwieranie czatu. Oczekiwanie na usługę rozmów.",
    ["Ordinary"] = "Zwykła",
    ["Page {page} / {pages}"] = "Strona {page} / {pages}",
    ["Page {page} of {pages}  |  {count} results"] = "Strona {page} z {pages}  |  Wyniki: {count}",
    ["Party: {count}"] = "Drużyna: {count}",
    ["Pending departure lost its vehicle binding."] = "Oczekujący odjazd utracił powiązanie z pojazdem.",
    ["Pending: {voice}"] = "Oczekuje: {voice}",
    ["Phone Chat messages"] = "Wiadomości Czatu w telefonie",
    ["Play spoken replies through the supported voice output. This does not change microphone capture."] = "Odtwarzaj wypowiedzi przez obsługiwane wyjście głosowe. Nie zmienia to przechwytywania mikrofonu.",
    ["Play voiced replies from your companions."] = "Odtwarzaj głosowe odpowiedzi towarzyszy.",
    ["Playback settings updated."] = "Ustawienia odtwarzania zaktualizowane.",
    ["Player memory"] = "Pamięć o graczu",
    ["Player unavailable"] = "Gracz niedostępny",
    ["Please wait for the current requests to finish."] = "Poczekaj, aż bieżące żądania się zakończą.",
    ["Pocket is light and fast on your CPU and starts speaking in about 0.2 s. OmniVoice sounds better, especially on harder voices, but needs a capable GPU and the optional OmniVoice pack (without it those entries are marked and cannot be applied), and the higher tiers take longer to start speaking, about 1 to 2.5 s. The Mistral cloud voice (Voxtral) speaks in each companion’s own voice using your Mistral key, whichever provider writes the replies; it needs a key and speaks English only. Convai uses its cloud; if a choice cannot run, a simpler voice takes over and you are told once."] = "Pocket jest lekki i szybki na procesorze i zaczyna mówić po ok. 0,2 s. OmniVoice brzmi lepiej, zwłaszcza przy trudniejszych głosach, ale wymaga wydajnego GPU i opcjonalnego pakietu OmniVoice (bez niego te pozycje są oznaczone i nie można ich zastosować), a wyższe poziomy zaczynają mówić dłużej, po ok. 1-2,5 s. Głos w chmurze Mistral (Voxtral) mówi własnym głosem każdego towarzysza, korzystając z twojego klucza Mistral, niezależnie od tego, który dostawca pisze odpowiedzi; wymaga klucza i mówi tylko po angielsku. Convai korzysta z chmury; jeśli wybrana opcja nie może działać, przejmuje prostszy głos i dostajesz jednorazowe powiadomienie.",
    ["Pocket · Performance"] = "Pocket · Wydajność",
    ["Prepares the conversation with a character you look at, walk up to or have just talked to, so they answer without a wait; it pauses during combat and scenes. At most two characters are kept ready at any moment, at most one new connection starts every 3 seconds and a character is released after 40 seconds unused, so a crowd never adds up."] = "Przygotowuje rozmowę z postacią, na którą patrzysz, do której podchodzisz lub z którą przed chwilą rozmawiano, aby odpowiadała bez czekania; podczas walk i scen jest wstrzymane. Jednocześnie gotowe są najwyżej dwie postacie, nowe połączenie jest nawiązywane najwyżej raz na 3 sekundy, a nieużywana postać jest zwalniana po 40 sekundach, więc tłum nigdy się nie kumuluje.",
    ["Preparing a reply"] = "Przygotowywanie odpowiedzi",
    ["Preparing connection to {name}…"] = "Przygotowywanie połączenia z: {name}…",
    ["Preparing to drive"] = "Przygotowanie do jazdy",
    ["Preparing voices"] = "Przygotowywanie głosów",
    ["Press Enter to write  /  Esc to stop typing"] = "Naciśnij Enter, aby pisać  /  Esc, aby przestać pisać",
    ["Press your Group voice chat shortcut to finish recording."] = "Naciśnij skrót Czat głosowy z grupą, aby zakończyć nagrywanie.",
    ["Press your Talk by voice shortcut to finish recording."] = "Naciśnij skrót Rozmowa głosem, aby zakończyć nagrywanie.",
