    ["Previous characters"] = "Poprzednie postacie",
    ["Previous models"] = "Poprzednie modele",
    ["Profile only"] = "Tylko profil",
    ["RED4ext logs"] = "Logi RED4ext",
    ["RED4ext writes its logs in {path}"] = "RED4ext zapisuje swoje logi w: {path}",
    ["Raise or lower where companions look when they make eye contact with you."] = "Podnieś lub obniż punkt, na który patrzą towarzysze, gdy nawiązują z tobą kontakt wzrokowy.",
    ["React to battles"] = "Reaguj na walki",
    ["React to collected loot"] = "Reaguj na zebrany łup",
    ["Reading installed models…"] = "Odczytywanie zainstalowanych modeli…",
    ["Reading models {read}/{total}"] = "Odczytywanie modeli {read}/{total}",
    ["Ready"] = "Gotowe",
    ["Ready · Unsaved selection"] = "Gotowe · Niezapisany wybór",
    ["Redscript log"] = "Log Redscript",
    ["Relationships"] = "Relacje",
    ["Talk to ordinary NPCs"] = "Rozmowy ze zwykłymi NPC",
    ["Conversation: {name} (archetype)"] = "Rozmowa: {name} (archetyp)",
    ["{count} of them can talk."] = "Rozmawiać może: {count}.",
    ["Lets you talk to unnamed people the game does not give a story role: gang members, NCPD officers, corporate guards, ripperdocs, shopkeepers, bartenders and passers-by. Each answers as their kind of person, does not know your story and does not remember you after you load a save, except shopkeepers you come back to. Named characters are not affected. On by default."] = "Pozwala rozmawiać z bezimiennymi osobami, którym gra nie daje roli w fabule: członkami gangów, funkcjonariuszami NCPD, ochroniarzami korporacji, ripperdocami, sklepikarzami, barmanami i przechodniami. Każdy odpowiada jak ktoś swojego pokroju, nie zna twojej historii i nie pamięta cię po wczytaniu zapisu, z wyjątkiem sklepikarzy, do których wracasz. Nie dotyczy postaci z imionami. Domyślnie włączone.",
    ["Releasing local voice memory"] = "Zwalnianie pamięci głosu lokalnego",
    ["Remember each companion’s prepared voice so summoning them again is quicker. Pocket TTS saves one small file per character (about 5 to 15 MB) in the mod’s runtime folder; OmniVoice does a short hidden warm-up at your chosen quality while a companion joins. Turn this off to save nothing on disk. The change applies without a restart."] = "Zapamiętuj przygotowany głos każdego towarzysza, aby ponowne przywołanie go było szybsze. Pocket TTS zapisuje jeden mały plik na postać (ok. 5-15 MB) w folderze uruchomieniowym moda; OmniVoice wykonuje krótką, ukrytą rozgrzewkę w wybranej jakości, gdy towarzysz dołącza. Wyłącz, aby nic nie zapisywać na dysku. Zmiana działa bez restartu.",
    ["Remove only this copy from your group."] = "Usuń z grupy tylko tę kopię.",
    ["Reopen the manager; that action is no longer available."] = "Otwórz menedżer ponownie; ta akcja nie jest już dostępna.",
    ["Reopen this page after the memory service reconnects. A pending clear keeps waiting for its own result."] = "Otwórz tę stronę ponownie po ponownym połączeniu usługi pamięci. Oczekujące czyszczenie nadal czeka na własny wynik.",
    ["Report for the developer"] = "Raport dla twórcy",
    ["Report path copied to the clipboard."] = "Ścieżka raportu skopiowana do schowka.",
    ["Report saved: {path}"] = "Raport zapisano: {path}",
    ["Request queued..."] = "Żądanie w kolejce...",
    ["Requires the optional OmniVoice pack (GPU)"] = "Wymaga opcjonalnego pakietu OmniVoice (GPU)",
    ["Return to Companion Manager."] = "Wróć do Menedżera towarzyszy.",
    ["Return to conversation settings."] = "Wróć do ustawień rozmów.",
    ["Return to the memory controls."] = "Wróć do ustawień pamięci.",
    ["Review the memory clear below, then choose Confirm or Cancel."] = "Sprawdź poniższe czyszczenie pamięci, a potem wybierz Potwierdź lub Anuluj.",
    ["Romantic"] = "Romantyczna",
    ["Running"] = "Działa",
    ["SELECTED"] = "WYBRANO",
    ["SETTINGS"] = "USTAWIENIA",
    ["Save a report file you can send to the developer. API keys, tokens, IDs, microphone audio and conversation text are left out. If the conversation service is not running, a shorter report is made from the files the game can read."] = "Zapisz plik raportu, który możesz wysłać twórcy. Klucze API, tokeny, identyfikatory, dźwięk z mikrofonu i treść rozmów są pomijane. Jeśli usługa rozmów nie działa, tworzony jest krótszy raport z plików, które gra może odczytać.",
    ["Saved Chat cleanup could not be verified. Please wait for the memory service."] = "Nie udało się zweryfikować wyczyszczenia zapisanego Czatu. Poczekaj na usługę pamięci.",
    ["Saved at {path}"] = "Zapisano w: {path}",
    ["Saved reports"] = "Zapisane raporty",
    ["Scenery or a vehicle is blocking the companion position."] = "Element otoczenia lub pojazd blokuje miejsce towarzysza.",
    ["Search a character by name. Each invitation reserves a place and starts preparation immediately."] = "Wyszukaj postać po imieniu. Każde zaproszenie rezerwuje miejsce i od razu rozpoczyna przygotowanie.",
    ["Search by character name or model record using Search settings. {query}"] = "Szukaj według imienia postaci lub rekordu modelu w polu wyszukiwania ustawień. {query}",
    ["Search by character name using Search settings. {query}\nThe character can be outside your current party."] = "Szukaj według imienia postaci w polu wyszukiwania ustawień. {query}\nPostać może nie należeć do obecnej drużyny.",
    ["Search names, models or settings..."] = "Szukaj imion, modeli lub ustawień...",
    ["Select a destination on the map first."] = "Najpierw wybierz cel na mapie.",
    ["Select {name} for memory controls. This does not invite them or change their conversation settings."] = "Wybierz: {name}, aby zarządzać pamięcią. To nie zaprasza postaci ani nie zmienia jej ustawień rozmów.",
    ["Selected"] = "Wybrane",
    ["Selected character"] = "Wybrana postać",
    ["Send the generated report rather than raw log files. Open these locations only if the developer asks for a specific file."] = "Wysyłaj wygenerowany raport zamiast surowych plików logów. Otwieraj te lokalizacje tylko wtedy, gdy twórca poprosi o konkretny plik.",
    ["Settings"] = "Ustawienia",
    ["Settings are active, but could not be saved for next time."] = "Ustawienia są aktywne, ale nie udało się zapisać ich na następny raz.",
    ["Settings saved."] = "Ustawienia zapisane.",
    ["Shared across your saves"] = "Wspólne dla wszystkich zapisów",
    ["Short report saved because the conversation service could not build the full report: {path}"] = "Zapisano krótki raport, ponieważ usługa rozmów nie mogła zbudować pełnego: {path}",
    ["Short report saved because the conversation service did not answer: {path}"] = "Zapisano krótki raport, ponieważ usługa rozmów nie odpowiedziała: {path}",
    ["Short report saved because the conversation service is not running: {path}"] = "Zapisano krótki raport, ponieważ usługa rozmów nie działa: {path}",
    ["Show companion replies using the selected subtitle display."] = "Pokazuj odpowiedzi towarzyszy w wybranym sposobie wyświetlania napisów.",
    ["Show companion reply subtitles during conversations."] = "Pokazuj napisy odpowiedzi towarzyszy podczas rozmów.",
    ["Some game models have special rigs or roles and may not behave as ordinary companions."] = "Niektóre modele z gry mają specjalne szkielety lub role i mogą nie zachowywać się jak zwykli towarzysze.",
    ["Some model records could not be read."] = "Nie udało się odczytać niektórych rekordów modeli.",
    ["Stand near one of your owned cars, or summon one."] = "Stań w pobliżu jednego ze swoich samochodów albo przywołaj któryś.",
    ["Stand near your owned car."] = "Stań w pobliżu swojego samochodu.",
    ["Starting"] = "Uruchamianie",
    ["Starting trip"] = "Rozpoczynanie przejazdu",
    ["State: {state}"] = "Stan: {state}",
    ["Step out and wait for the previous driver cleanup to finish."] = "Wysiądź i poczekaj, aż poprzednie sprzątanie po kierowcy się zakończy.",
    ["Step out before starting a new companion trip."] = "Wysiądź, zanim rozpoczniesz nowy przejazd z towarzyszem.",
    ["Step out of the driver seat before asking your companion to drive."] = "Opuść miejsce kierowcy, zanim poprosisz towarzysza o prowadzenie.",
    ["Step out of the driver seat so your companion can get in."] = "Opuść miejsce kierowcy, aby towarzysz mógł wsiąść.",
    ["Stop requested"] = "Zażądano zatrzymania",
    ["Stop the trip after returning to gameplay. Wait for the car to stop, then step out before dismissing the driver."] = "Zatrzymaj przejazd po powrocie do gry. Poczekaj, aż samochód stanie, a potem wysiądź, zanim odeślesz kierowcę.",
    ["Stop the trip and step out before dismissing your driver."] = "Zatrzymaj przejazd i wysiądź, zanim odeślesz kierowcę.",
    ["Stop trip"] = "Zatrzymaj przejazd",
    ["Stopped"] = "Zatrzymano",
    ["Stopping"] = "Zatrzymywanie",
    ["Stopping the trip. Wait for the car to stop before stepping out."] = "Zatrzymywanie przejazdu. Poczekaj, aż samochód stanie, zanim wysiądziesz.",
    ["Strong"] = "Silne",
    ["Subtitle display"] = "Wyświetlanie napisów",
    ["Subtitles"] = "Napisy",
    ["Subtle"] = "Subtelne",
    ["Support report saved: {path}"] = "Raport pomocy zapisano: {path}",
    ["TALK TO {character}"] = "ROZMOWA: {character}",
    ["TEXT  >"] = "TEKST  >",
    ["Talk to companions in any language: each character answers in the language you use. It uses a multilingual copy of each character, so what they remember from these conversations is kept apart from your English ones; forgetting a character clears both. Pocket TTS speaks only English, so turning this on switches Companion voices to OmniVoice · Balanced when the optional OmniVoice pack is installed, or to Convai · Cloud voice otherwise; without the pack, Natural speech and Expressive emotions are turned off, because the cloud voice would read their tags aloud. Off by default."] = "Rozmawiaj z towarzyszami w dowolnym języku: każda postać odpowiada w języku, którego używasz. Wykorzystuje wielojęzyczną kopię każdej postaci, więc to, co pamięta z tych rozmów, jest przechowywane osobno od twoich rozmów po angielsku; zapomnienie postaci usuwa wspomnienia z jednych i drugich. Pocket TTS mówi tylko po angielsku, więc włączenie tej opcji przełącza Głosy towarzyszy na OmniVoice · Zrównoważona, gdy zainstalowano opcjonalny pakiet OmniVoice, a w przeciwnym razie na Convai · Głos w chmurze; bez pakietu Naturalna mowa i Wyraziste emocje zostają wyłączone, bo głos w chmurze czytałby ich znaczniki na głos. Domyślnie wyłączone.",
    ["Pocket TTS speaks only English. Turn off Multilingual conversations to choose it."] = "Pocket TTS mówi tylko po angielsku. Wyłącz Rozmowy wielojęzyczne, aby go wybrać.",
    ["Multilingual conversations needs a voice that speaks every language, so {setting} was switched to {voice}."] = "Rozmowy wielojęzyczne wymagają głosu mówiącego we wszystkich językach, więc zmieniono ustawienie {setting} na: {voice}.",
    ["Natural speech and Expressive emotions need the OmniVoice pack while Multilingual conversations is on: the Convai cloud voice would read their tags aloud."] = "Naturalna mowa i Wyraziste emocje wymagają pakietu OmniVoice, gdy włączone są Rozmowy wielojęzyczne: głos w chmurze Convai czytałby ich znaczniki na głos.",
    ["Natural speech and Expressive emotions were turned off: the Convai cloud voice would read their tags aloud. With the OmniVoice pack, all three work together."] = "Naturalna mowa i Wyraziste emocje zostały wyłączone: głos w chmurze Convai czytałby ich znaczniki na głos. Z pakietem OmniVoice wszystkie trzy działają razem.",
    ["The Convai cloud voice cannot use Natural speech or Expressive emotions, so they were turned off."] = "Głos w chmurze Convai nie może używać ustawień „Naturalna mowa” i „Wyraziste emocje”, więc zostały wyłączone.",
