    ["Play"] = "Odtwórz",
    ["Plays one of this character’s own lines from the game, through the game’s normal dialogue audio, so you can compare their companion voice with it. You hear it when you return to gameplay; each press tries another line, and a character may have no line for some of them."] = "Odtwarza jedną z własnych kwestii tej postaci z gry przez zwykły dźwięk dialogów gry, aby można było porównać z nią jej głos towarzysza. Usłyszysz ją po powrocie do gry; każde naciśnięcie próbuje innej kwestii, a postać może nie mieć kwestii dla niektórych z nich.",
    ["{name} will say one of their game lines when you return to the game."] = "Po powrocie do gry powie jedną ze swoich kwestii z gry: {name}.",
    ["Lip sync delay (Bluetooth)"] = "Opóźnienie synchronizacji ust (Bluetooth)",
    ["Bluetooth earbuds and headphones play sound a little later than the picture, so lips and subtitles can run slightly ahead of the voice. This holds them back to match, for every voice. Auto uses 150 ms while Windows plays through a Bluetooth device and none otherwise; choose a value if your headset is faster or slower. The game’s own dialogue has the same Bluetooth delay and does not correct it."] = "Słuchawki Bluetooth odtwarzają dźwięk nieco później niż obraz, więc usta i napisy mogą lekko wyprzedzać głos. To ustawienie je opóźnia, aby pasowały, dla wszystkich głosów. Automatycznie: 150 ms, gdy Windows odtwarza przez urządzenie Bluetooth, w przeciwnym razie brak; wybierz wartość, jeśli twoje słuchawki są szybsze lub wolniejsze. Dialogi samej gry mają takie samo opóźnienie Bluetooth i gra go nie koryguje.",
    ["Choose one of the listed lip sync delays."] = "Wybierz jedno z podanych opóźnień synchronizacji ust.",
    ["Behavior: {list}"] = "Zachowanie: {list}",
    ["In your party: {count}"] = "W twojej drużynie: {count}",
    ["Memory: remembers your conversations"] = "Pamięć: pamięta twoje rozmowy",
    ["Multilingual: replies in your language"] = "Wielojęzycznie: odpowiada w twoim języku",
    ["Relationship: {mode}"] = "Relacja: {mode}",
    ["Speech: {list}"] = "Mowa: {list}",
    ["Added"] = "Dodano",
    ["Added (ends in {tail})"] = "Dodano (kończy się na {tail})",
    ["Checking…"] = "Sprawdzanie…",
    ["Convai API key"] = "Klucz API Convai",
    ["Convai did not accept that key."] = "Convai nie przyjęło tego klucza.",
    ["Convai did not accept your API key. Check it in Settings > Development."] = "Convai nie przyjęło twojego klucza API. Sprawdź go w Ustawieniach > Dla programistów.",
    ["Conversations use"] = "Rozmowy używają",
    ["You’ve reached today’s free conversation limit. Convai (better quality responses) is back tomorrow. To keep talking now, add a free Mistral key and set Conversation provider to Mistral in Settings > Development. A fully local option is coming."] = "Wykorzystałeś dzisiejszy darmowy limit rozmów. Convai (lepsza jakość odpowiedzi) wróci jutro. Aby kontynuować od razu, dodaj darmowy klucz Mistral i ustaw Dostawcę rozmów na Mistral w Ustawieniach > Dla programistów. Wkrótce pojawi się też opcja w pełni lokalna.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Development."] = "Osiągnięto limit rozmów. Spróbuj ponownie później albo dodaj darmowy klucz Mistral i ustaw Dostawcę rozmów na Mistral w Ustawieniach > Dla programistów.",
    ["Mistral’s free limit is reached for now. Try again in a moment."] = "Darmowy limit Mistral został chwilowo osiągnięty. Spróbuj ponownie za chwilę.",
    ["Use a Convai API key of your own for conversations. Paste it below, turn this on and choose Apply. The change waits until no conversation is running."] = "Użyj własnego klucza API Convai do rozmów. Wklej go poniżej, włącz tę opcję i wybierz Zastosuj. Zmiana czeka, aż żadna rozmowa nie będzie trwać.",
    ["Copy your key first. It is read from the clipboard once, checked with Convai and saved on this computer."] = "Najpierw skopiuj swój klucz. Jest odczytywany ze schowka jednorazowo, sprawdzany w Convai i zapisywany na tym komputerze.",
    ["Deletes the saved key. Conversations go back to the shared plan."] = "Usuwa zapisany klucz. Rozmowy wracają do wspólnego planu.",
    ["Not added"] = "Nie dodano",
    ["Paste Convai API key"] = "Wklej klucz API Convai",
    ["Paste from clipboard"] = "Wklej ze schowka",
    ["Remove"] = "Usuń",
    ["Remove my Convai API key"] = "Usuń mój klucz API Convai",
    ["Saved on this computer only. Only the last four characters are ever shown."] = "Zapisany tylko na tym komputerze. Zawsze widać tylko ostatnie cztery znaki.",
    ["Shared plan: daily limit reached"] = "Wspólny plan: dzienny limit wyczerpany",
    ["Shared plan: limit used up"] = "Wspólny plan: limit wyczerpany",
    ["The clipboard could not be read."] = "Nie udało się odczytać schowka.",
    ["The clipboard does not hold a Convai API key."] = "Schowek nie zawiera klucza API Convai.",
    ["The clipboard is empty. Copy your key first."] = "Schowek jest pusty. Najpierw skopiuj swój klucz.",
    ["The key could not be saved."] = "Nie udało się zapisać klucza.",
    ["The request could not be sent. Try again."] = "Nie udało się wysłać żądania. Spróbuj ponownie.",
    ["The shared plan"] = "Wspólny plan",
    ["The shared plan: {left} of {limit} left today"] = "Wspólny plan: dziś zostało {left} z {limit}",
    ["Use my own Convai API key"] = "Użyj własnego klucza API Convai",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Development."] = "Twój klucz API Convai osiągnął limit planu. Spróbuj ponownie później albo dodaj inny klucz w Ustawieniach > Dla programistów.",
    ["Your key was removed."] = "Twój klucz został usunięty.",
    ["Your key: not accepted"] = "Twój klucz: nie przyjęty",
    ["Your key: plan limit reached"] = "Twój klucz: osiągnięto limit planu",
    ["Your own key"] = "Własny klucz",
    ["Your Convai plan cannot hold the memory these conversations need. Free a memory user in your Convai account or use another key."] = "Twój plan Convai nie może pomieścić pamięci, której potrzebują te rozmowy. Zwolnij użytkownika pamięci na swoim koncie Convai albo użyj innego klucza.",
    ["Your Convai plan has no room for conversation memory, so companions will not remember past talks."] = "Twój plan Convai nie ma miejsca na pamięć rozmów, więc towarzysze nie będą pamiętać wcześniejszych rozmów.",
    ["Your key: no room for memory"] = "Twój klucz: brak miejsca na pamięć",
    ["Your own key, without memory"] = "Własny klucz, bez pamięci",
    ["Choose one of the listed conversation providers."] = "Wybierz jednego z podanych dostawców rozmów.",
    ["Convai free tier"] = "Convai (darmowy plan)",
    ["Convai: Mistral has no key yet"] = "Convai: Mistral nie ma jeszcze klucza",
    ["Conversation provider"] = "Dostawca rozmów",
    ["Copy your free key from Mistral first. It is read from the clipboard once, checked with Mistral and saved on this computer. You can also save it in the file player-mistral-key.txt in the conversation service folder."] = "Najpierw skopiuj swój darmowy klucz z serwisu Mistral. Zostanie odczytany ze schowka raz, sprawdzony przez Mistral i zapisany na tym komputerze. Możesz też zapisać go w pliku player-mistral-key.txt w folderze usługi rozmów.",
    ["Deletes the saved key. Conversations go back to Convai free tier."] = "Usuwa zapisany klucz. Rozmowy wracają do Convai (darmowy plan).",
    ["Mistral (free plan)"] = "Mistral (darmowy plan)",
    ["Mistral did not accept that key."] = "Mistral nie zaakceptował tego klucza.",
    ["Mistral did not accept your key. Check it in Settings > Development."] = "Mistral nie zaakceptował twojego klucza. Sprawdź go w Ustawieniach > Dla programistów.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Development."] = "Mistral nie ma jeszcze klucza, więc używane jest Convai. Dodaj swój klucz w Ustawieniach > Dla programistów.",
    ["Mistral key"] = "Klucz Mistral",
    ["Mistral replies are spoken by a local voice instead of the Convai cloud voice."] = "Odpowiedzi Mistral wypowiada lokalny głos, a nie chmurowy głos Convai.",
    ["Mistral: free limit reached for now"] = "Mistral: darmowy limit chwilowo osiągnięty",
    ["Mistral: key not accepted"] = "Mistral: klucz nie został zaakceptowany",
    ["Mistral: model unavailable"] = "Mistral: model niedostępny",
    ["Paste Mistral key"] = "Wklej klucz Mistral",
    ["Remove my Mistral key"] = "Usuń mój klucz Mistral",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Development, or type your message."] = "Mówienie do towarzyszy na razie wymaga Convai. Ustaw opcję Dostawca rozmów na Convai (darmowy plan) w Ustawieniach > Dla programistów albo wpisz wiadomość.",
    ["The Mistral model is unavailable right now. Try again in a minute."] = "Model Mistral jest teraz niedostępny. Spróbuj ponownie za minutę.",
    ["Waiting for the conversation to end"] = "Czekanie na zakończenie rozmowy",
    ["Which provider answers your conversations right now and, for Convai, which plan pays for them. Changes wait until no conversation is running."] = "Który dostawca obsługuje teraz twoje rozmowy oraz, w przypadku Convai, który plan za nie płaci. Zmiany czekają, aż żadna rozmowa nie będzie trwać.",
    ["Who writes your companions’ replies. Convai is the default and the recommended choice, with better quality responses. Mistral uses its free plan with your own free key (add it below; signing up needs phone verification): memory stays on this computer, and the free plan allows about one message a second and a monthly allowance. A Convai cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works. The change waits until no conversation is running; choose Apply."] = "Kto pisze odpowiedzi twoich towarzyszy. Convai jest domyślne i zalecane, z lepszą jakością odpowiedzi. Mistral korzysta z darmowego planu z twoim własnym darmowym kluczem (dodaj go poniżej; rejestracja wymaga weryfikacji telefonu): pamięć zostaje na tym komputerze, a darmowy plan pozwala na około jedną wiadomość na sekundę i miesięczny przydział. Chmurowy głos Convai zostaje zastąpiony lokalnym głosem. Mowa jest rozpoznawana na tym komputerze, więc klawisz głosowy działa. Zmiana czeka, aż żadna rozmowa nie będzie trwać; wybierz Zastosuj.",
    ["Who writes your companions’ replies. Convai is the default and the recommended choice, with better quality responses. Mistral uses its free plan with your own free key (add it below; signing up needs phone verification): memory stays on this computer, and the free plan allows about one message a second and a monthly allowance. A Convai cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with Mistral, so type your messages. The change waits until no conversation is running; choose Apply."] = "Kto pisze odpowiedzi twoich towarzyszy. Convai jest domyślne i zalecane, z lepszą jakością odpowiedzi. Mistral korzysta z darmowego planu z twoim własnym darmowym kluczem (dodaj go poniżej; rejestracja wymaga weryfikacji telefonu): pamięć zostaje na tym komputerze, a darmowy plan pozwala na około jedną wiadomość na sekundę i miesięczny przydział. Chmurowy głos Convai zostaje zastąpiony lokalnym głosem. Rozpoznawanie mowy dla klawisza głosowego nie jest jeszcze dostępne z Mistral, więc wpisuj wiadomości. Zmiana czeka, aż żadna rozmowa nie będzie trwać; wybierz Zastosuj.",
    ["Convai: Groq has no key yet"] = "Convai: Groq nie ma jeszcze klucza",
    ["Convai: Local AI is not ready"] = "Convai: Lokalne AI nie jest gotowe",
    ["Copy your free key from Groq first. It is read from the clipboard once, checked with Groq and saved on this computer. You can also save it in the file player-groq-key.txt in the conversation service folder."] = "Najpierw skopiuj swój darmowy klucz z Groq. Zostanie odczytany ze schowka jednorazowo, sprawdzony przez Groq i zapisany na tym komputerze. Możesz go też zapisać w pliku player-groq-key.txt w folderze usługi rozmów.",
    ["Deletes the saved key. Conversations go back to Mistral if you added a key there, otherwise to Convai free tier."] = "Usuwa zapisany klucz. Rozmowy wrócą do Mistral, jeśli dodano tam klucz, a w przeciwnym razie do Convai (darmowy plan).",
    ["Groq (free plan)"] = "Groq (darmowy plan)",
    ["Groq did not accept that key."] = "Groq nie zaakceptował tego klucza.",
    ["Groq did not accept your key. Check it in Settings > Development."] = "Groq nie zaakceptował twojego klucza. Sprawdź go w Ustawieniach > Dla programistów.",
    ["Groq has no key yet, so Convai is used. Add your key in Settings > Development."] = "Groq nie ma jeszcze klucza, więc używane jest Convai. Dodaj swój klucz w Ustawieniach > Dla programistów.",
    ["Groq key"] = "Klucz Groq",
    ["Groq: free limit reached for now"] = "Groq: darmowy limit chwilowo osiągnięty",
    ["Groq: key not accepted"] = "Groq: klucz nie został zaakceptowany",
    ["Groq: model unavailable"] = "Groq: model niedostępny",
    ["Groq’s free limit is reached for now. Try again in a moment."] = "Darmowy limit Groq został chwilowo osiągnięty. Spróbuj ponownie za chwilę.",
    ["Local (needs Local AI pack)"] = "Lokalnie (wymaga pakietu Lokalne AI)",
    ["Local AI"] = "Lokalne AI",
    ["Local AI (this computer)"] = "Lokalne AI (ten komputer)",
    ["Local AI could not start, so a cloud provider is used. Check Local AI in Settings > Development."] = "Lokalne AI nie mogło się uruchomić, więc używany jest dostawca chmurowy. Sprawdź Lokalne AI w Ustawieniach > Dla programistów.",
    ["Not enough graphics memory"] = "Za mało pamięci graficznej",
    ["Paste Groq key"] = "Wklej klucz Groq",
    ["Remove my Groq key"] = "Usuń mój klucz Groq",
    ["Runs conversations on this computer with the optional Local AI pack. It needs free graphics memory while it works, and memory stays on this computer. Choose Local in Conversation provider, then Apply."] = "Prowadzi rozmowy na tym komputerze z opcjonalnym pakietem Lokalne AI. Podczas pracy potrzebuje wolnej pamięci graficznej, a pamięć pozostaje na tym komputerze. Wybierz Lokalnie w polu Dostawca rozmów, a potem Zastosuj.",
    ["The Groq model is unavailable right now. Try again in a minute."] = "Model Groq jest teraz niedostępny. Spróbuj ponownie za minutę.",
    ["Warming up"] = "Rozgrzewanie",
    ["Mistral cloud voice (Voxtral)"] = "Głos w chmurze Mistral (Voxtral)",
    ["{voice} · needs Mistral key"] = "{voice} · wymaga klucza Mistral",
    ["The Mistral cloud voice speaks only English here. Turn off Multilingual conversations to choose it."] = "Głos w chmurze Mistral mówi tu tylko po angielsku. Wyłącz Rozmowy wielojęzyczne, aby go wybrać.",
    ["Requires a Mistral key (add it in Settings > Development)"] = "Wymaga klucza Mistral (dodaj go w Ustawieniach > Dla programistów)",
}
